"""Sortie C0, batch 3: linearity of the segment integral and the ML inequality."""
import sys, os; sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')); from c0lib import *
only = sys.argv[1:]
def run(w):
    if only and w.label not in only: return True
    return w.run()

# ---- lintadd
w = W('lintadd', 'The segment integral of a sum of two continuous functions.')
A = '( %s /\\ G e. ( D -cn-> CC ) )' % PH; A2 = '( %s /\\ t e. ( 0 (,) 1 ) )' % A
a, b, f, g = phctx(w, A, True); gc = w.s([], 'simpr', '( %s -> G e. ( D -cn-> CC ) )' % A); p = w.s([], 'simpl', '( %s -> %s )' % (A, PH))
FG = '( F oF + G )'
ox = w.s([], 'ovexd', '( %s -> %s e. _V )' % (A, FG))
v = w.s([ox, a, b, w.inst('lintval')], 'syl3anc', '( %s -> %s = %s )' % (A, LINT(FG, 'A', 'B'), ITG(O01, INTG(FG, 'A', 'B'))))
vf = w.s([f, a, b, w.inst('lintval')], 'syl3anc', '( %s -> %s = %s )' % (A, LINT('F', 'A', 'B'), ITG(O01, INTG('F', 'A', 'B'))))
vg = w.s([gc, a, b, w.inst('lintval')], 'syl3anc', '( %s -> %s = %s )' % (A, LINT('G', 'A', 'B'), ITG(O01, INTG('G', 'A', 'B'))))
# pointwise
a2 = w.s([a], 'adantr', '( %s -> A e. CC )' % A2); b2 = w.s([b], 'adantr', '( %s -> B e. CC )' % A2); f2 = w.s([f], 'adantr', '( %s -> F e. ( D -cn-> CC ) )' % A2)
g2 = w.s([g], 'adantr', '( %s -> ( A cseg B ) C_ D )' % A2); gc2 = w.s([gc], 'adantr', '( %s -> G e. ( D -cn-> CC ) )' % A2)
to = w.s([], 'simpr', '( %s -> t e. ( 0 (,) 1 ) )' % A2); ss = closed(w, A2, 'ioossicc', '( 0 (,) 1 ) C_ ( 0 [,] 1 )'); t01 = w.s([ss, to], 'sseldd', '( %s -> t e. ( 0 [,] 1 ) )' % A2)
clf, ld, ff = intgclg(w, A2, a2, b2, f2, g2, t01, 'F'); clg, _, gf = intgclg(w, A2, a2, b2, gc2, g2, t01, 'G')
ffn = w.s([ff], 'ffnd', '( %s -> F Fn D )' % A2); gfn = w.s([gf], 'ffnd', '( %s -> G Fn D )' % A2)
dc = w.s([f2, w.inst('cncfrss')], 'syl', '( %s -> D C_ CC )' % A2); cx = closed(w, A2, 'cnex', 'CC e. _V'); dx = w.s([cx, dc], 'ssexd', '( %s -> D e. _V )' % A2)
ini = w.s([], 'inidm', '( D i^i D ) = D')
L = LIN('A', 'B')
e1 = w.s([], 'eqidd', '( ( %s /\\ %s e. D ) -> ( F ` %s ) = ( F ` %s ) )' % (A2, L, L, L)); e2 = w.s([], 'eqidd', '( ( %s /\\ %s e. D ) -> ( G ` %s ) = ( G ` %s ) )' % (A2, L, L, L))
of = w.s([ffn, gfn, dx, dx, ini, e1, e2], 'ofval', '( ( %s /\\ %s e. D ) -> ( %s ` %s ) = ( ( F ` %s ) + ( G ` %s ) ) )' % (A2, L, FG, L, L, L))
of2 = w.s([ld, of], 'mpdan', '( %s -> ( %s ` %s ) = ( ( F ` %s ) + ( G ` %s ) ) )' % (A2, FG, L, L, L))
of3 = w.s([of2], 'oveq1d', '( %s -> %s = ( ( ( F ` %s ) + ( G ` %s ) ) x. ( B - A ) ) )' % (A2, INTG(FG, 'A', 'B'), L, L))
fv = w.s([ff, ld], 'ffvelcdmd', '( %s -> ( F ` %s ) e. CC )' % (A2, L)); gv = w.s([gf, ld], 'ffvelcdmd', '( %s -> ( G ` %s ) e. CC )' % (A2, L)); ba = w.s([b2, a2], 'subcld', '( %s -> ( B - A ) e. CC )' % A2)
dd = w.s([fv, gv, ba], 'adddird', '( %s -> ( ( ( F ` %s ) + ( G ` %s ) ) x. ( B - A ) ) = ( %s + %s ) )' % (A2, L, L, INTG('F', 'A', 'B'), INTG('G', 'A', 'B')))
of4 = w.s([of3, dd], 'eqtrd', '( %s -> %s = ( %s + %s ) )' % (A2, INTG(FG, 'A', 'B'), INTG('F', 'A', 'B'), INTG('G', 'A', 'B')))
ie = w.s([of4], 'itgeq2dv', '( %s -> %s = %s )' % (A, ITG(O01, INTG(FG, 'A', 'B')), ITG(O01, '( %s + %s )' % (INTG('F', 'A', 'B'), INTG('G', 'A', 'B')))))
ibf = w.s([p, w.inst('lintibl')], 'syl', '( %s -> ( t e. ( 0 (,) 1 ) |-> %s ) e. L^1 )' % (A, INTG('F', 'A', 'B')))
ab = w.s([a, b], 'jca', '( %s -> ( A e. CC /\\ B e. CC ) )' % A); gg = w.s([gc, g], 'jca', '( %s -> ( G e. ( D -cn-> CC ) /\\ ( A cseg B ) C_ D ) )' % A)
pg = w.s([ab, gg], 'jca', '( %s -> ( ( A e. CC /\\ B e. CC ) /\\ ( G e. ( D -cn-> CC ) /\\ ( A cseg B ) C_ D ) ) )' % A)
ibg = w.s([pg, w.inst('lintibl')], 'syl', '( %s -> ( t e. ( 0 (,) 1 ) |-> %s ) e. L^1 )' % (A, INTG('G', 'A', 'B')))
ia = w.s([clf, ibf, clg, ibg], 'itgadd', '( %s -> %s = ( %s + %s ) )' % (A, ITG(O01, '( %s + %s )' % (INTG('F', 'A', 'B'), INTG('G', 'A', 'B'))), ITG(O01, INTG('F', 'A', 'B')), ITG(O01, INTG('G', 'A', 'B'))))
s1 = w.s([v, ie], 'eqtrd', '( %s -> %s = %s )' % (A, LINT(FG, 'A', 'B'), ITG(O01, '( %s + %s )' % (INTG('F', 'A', 'B'), INTG('G', 'A', 'B')))))
s2 = w.s([s1, ia], 'eqtrd', '( %s -> %s = ( %s + %s ) )' % (A, LINT(FG, 'A', 'B'), ITG(O01, INTG('F', 'A', 'B')), ITG(O01, INTG('G', 'A', 'B'))))
s3 = w.s([vf, vg], 'oveq12d', '( %s -> ( %s + %s ) = ( %s + %s ) )' % (A, LINT('F', 'A', 'B'), LINT('G', 'A', 'B'), ITG(O01, INTG('F', 'A', 'B')), ITG(O01, INTG('G', 'A', 'B'))))
w.qed([s2, s3], 'eqtr4d', '( %s -> %s = ( %s + %s ) )' % (A, LINT(FG, 'A', 'B'), LINT('F', 'A', 'B'), LINT('G', 'A', 'B'))); run(w)

# ---- lintmulc
w = W('lintmulc', 'The segment integral of a constant multiple of a continuous function.')
A = '( %s /\\ C e. CC )' % PH; A2 = '( %s /\\ t e. ( 0 (,) 1 ) )' % A
a, b, f, g = phctx(w, A, True); cc = w.s([], 'simpr', '( %s -> C e. CC )' % A); p = w.s([], 'simpl', '( %s -> %s )' % (A, PH))
CF = '( ( D X. { C } ) oF x. F )'
ox = w.s([], 'ovexd', '( %s -> %s e. _V )' % (A, CF))
v = w.s([ox, a, b, w.inst('lintval')], 'syl3anc', '( %s -> %s = %s )' % (A, LINT(CF, 'A', 'B'), ITG(O01, INTG(CF, 'A', 'B'))))
vf = w.s([f, a, b, w.inst('lintval')], 'syl3anc', '( %s -> %s = %s )' % (A, LINT('F', 'A', 'B'), ITG(O01, INTG('F', 'A', 'B'))))
a2 = w.s([a], 'adantr', '( %s -> A e. CC )' % A2); b2 = w.s([b], 'adantr', '( %s -> B e. CC )' % A2); f2 = w.s([f], 'adantr', '( %s -> F e. ( D -cn-> CC ) )' % A2)
g2 = w.s([g], 'adantr', '( %s -> ( A cseg B ) C_ D )' % A2); cc2 = w.s([cc], 'adantr', '( %s -> C e. CC )' % A2)
to = w.s([], 'simpr', '( %s -> t e. ( 0 (,) 1 ) )' % A2); ss = closed(w, A2, 'ioossicc', '( 0 (,) 1 ) C_ ( 0 [,] 1 )'); t01 = w.s([ss, to], 'sseldd', '( %s -> t e. ( 0 [,] 1 ) )' % A2)
clf, ld, ff = intgclg(w, A2, a2, b2, f2, g2, t01, 'F')
ffn = w.s([ff], 'ffnd', '( %s -> F Fn D )' % A2)
dc = w.s([f2, w.inst('cncfrss')], 'syl', '( %s -> D C_ CC )' % A2); cx = closed(w, A2, 'cnex', 'CC e. _V'); dx = w.s([cx, dc], 'ssexd', '( %s -> D e. _V )' % A2)
L = LIN('A', 'B')
e1 = w.s([], 'eqidd', '( ( %s /\\ %s e. D ) -> ( F ` %s ) = ( F ` %s ) )' % (A2, L, L, L))
of = w.s([dx, cc2, ffn, e1], 'ofc1', '( ( %s /\\ %s e. D ) -> ( %s ` %s ) = ( C x. ( F ` %s ) ) )' % (A2, L, CF, L, L))
of2 = w.s([ld, of], 'mpdan', '( %s -> ( %s ` %s ) = ( C x. ( F ` %s ) ) )' % (A2, CF, L, L))
of3 = w.s([of2], 'oveq1d', '( %s -> %s = ( ( C x. ( F ` %s ) ) x. ( B - A ) ) )' % (A2, INTG(CF, 'A', 'B'), L))
fv = w.s([ff, ld], 'ffvelcdmd', '( %s -> ( F ` %s ) e. CC )' % (A2, L)); ba = w.s([b2, a2], 'subcld', '( %s -> ( B - A ) e. CC )' % A2)
ma = w.s([cc2, fv, ba], 'mulassd', '( %s -> ( ( C x. ( F ` %s ) ) x. ( B - A ) ) = ( C x. %s ) )' % (A2, L, INTG('F', 'A', 'B')))
of4 = w.s([of3, ma], 'eqtrd', '( %s -> %s = ( C x. %s ) )' % (A2, INTG(CF, 'A', 'B'), INTG('F', 'A', 'B')))
ie = w.s([of4], 'itgeq2dv', '( %s -> %s = %s )' % (A, ITG(O01, INTG(CF, 'A', 'B')), ITG(O01, '( C x. %s )' % INTG('F', 'A', 'B'))))
ibf = w.s([p, w.inst('lintibl')], 'syl', '( %s -> ( t e. ( 0 (,) 1 ) |-> %s ) e. L^1 )' % (A, INTG('F', 'A', 'B')))
im = w.s([cc, clf, ibf], 'itgmulc2', '( %s -> ( C x. %s ) = %s )' % (A, ITG(O01, INTG('F', 'A', 'B')), ITG(O01, '( C x. %s )' % INTG('F', 'A', 'B'))))
s1 = w.s([v, ie], 'eqtrd', '( %s -> %s = %s )' % (A, LINT(CF, 'A', 'B'), ITG(O01, '( C x. %s )' % INTG('F', 'A', 'B'))))
s2 = w.s([s1, im], 'eqtr4d', '( %s -> %s = ( C x. %s ) )' % (A, LINT(CF, 'A', 'B'), ITG(O01, INTG('F', 'A', 'B'))))
s3 = w.s([vf], 'oveq2d', '( %s -> ( C x. %s ) = ( C x. %s ) )' % (A, LINT('F', 'A', 'B'), ITG(O01, INTG('F', 'A', 'B'))))
w.qed([s2, s3], 'eqtr4d', '( %s -> %s = ( C x. %s ) )' % (A, LINT(CF, 'A', 'B'), LINT('F', 'A', 'B'))); run(w)

# ---- lintabs (the ML inequality)
w = W('lintabs', 'The ML inequality: a segment integral is bounded by a bound of the integrand times the length of the segment.')
A = '( %s /\\ M e. RR /\\ A. z e. ( A cseg B ) ( abs ` ( F ` z ) ) <_ M )' % PH; A2 = '( %s /\\ t e. ( 0 (,) 1 ) )' % A
p = w.s([], 'simp1', '( %s -> %s )' % (A, PH)); m = w.s([], 'simp2', '( %s -> M e. RR )' % A); h = w.s([], 'simp3', '( %s -> A. z e. ( A cseg B ) ( abs ` ( F ` z ) ) <_ M )' % A)
a, b, f, g = phfrom(w, A, p)
K = '( M x. ( abs ` ( B - A ) ) )'; L = LIN('A', 'B'); I = INTG('F', 'A', 'B')
v = w.s([f, a, b, w.inst('lintval')], 'syl3anc', '( %s -> %s = %s )' % (A, LINT('F', 'A', 'B'), ITG(O01, I)))
va = w.s([v], 'fveq2d', '( %s -> ( abs ` %s ) = ( abs ` %s ) )' % (A, LINT('F', 'A', 'B'), ITG(O01, I)))
p2 = w.s([p], 'adantr', '( %s -> %s )' % (A2, PH)); a2, b2, f2, g2 = phfrom(w, A2, p2)
to = w.s([], 'simpr', '( %s -> t e. ( 0 (,) 1 ) )' % A2); ss = closed(w, A2, 'ioossicc', '( 0 (,) 1 ) C_ ( 0 [,] 1 )'); t01 = w.s([ss, to], 'sseldd', '( %s -> t e. ( 0 [,] 1 ) )' % A2)
cl, ld, ff = intgclg(w, A2, a2, b2, f2, g2, t01, 'F')
ib = w.s([p, w.inst('lintibl')], 'syl', '( %s -> ( t e. ( 0 (,) 1 ) |-> %s ) e. L^1 )' % (A, I))
ab1 = w.s([cl, ib], 'itgabs', '( %s -> ( abs ` %s ) <_ %s )' % (A, ITG(O01, I), ITG(O01, '( abs ` %s )' % I)))
# itgle
ibab = w.s([cl, ib], 'iblabs', '( %s -> ( t e. ( 0 (,) 1 ) |-> ( abs ` %s ) ) e. L^1 )' % (A, I))
v1, mb, vr = vol01(w, A)
ba = w.s([b, a], 'subcld', '( %s -> ( B - A ) e. CC )' % A); bar = w.s([ba], 'abscld', '( %s -> ( abs ` ( B - A ) ) e. RR )' % A)
kr = w.s([m, bar], 'remulcld', '( %s -> %s e. RR )' % (A, K)); kc = w.s([kr], 'recnd', '( %s -> %s e. CC )' % (A, K))
ic = w.s([mb, vr, kc, w.inst('iblconst')], 'syl3anc', '( %s -> ( ( 0 (,) 1 ) X. { %s } ) e. L^1 )' % (A, K))
fc = closed(w, A, 'fconstmpt', '( ( 0 (,) 1 ) X. { %s } ) = ( t e. ( 0 (,) 1 ) |-> %s )' % (K, K))
ik = w.s([fc, ic], 'eqeltrrd', '( %s -> ( t e. ( 0 (,) 1 ) |-> %s ) e. L^1 )' % (A, K))
absr = w.s([cl], 'abscld', '( %s -> ( abs ` %s ) e. RR )' % (A2, I)); kr2 = w.s([kr], 'adantr', '( %s -> %s e. RR )' % (A2, K))
fv = w.s([ff, ld], 'ffvelcdmd', '( %s -> ( F ` %s ) e. CC )' % (A2, L)); ba2 = w.s([ba], 'adantr', '( %s -> ( B - A ) e. CC )' % A2)
am = w.s([fv, ba2, w.inst('absmul')], 'syl2anc', '( %s -> ( abs ` %s ) = ( ( abs ` ( F ` %s ) ) x. ( abs ` ( B - A ) ) ) )' % (A2, I, L))
sb1 = w.s([], 'fveq2', '( z = %s -> ( F ` z ) = ( F ` %s ) )' % (L, L)); sb2 = w.s([sb1], 'fveq2d', '( z = %s -> ( abs ` ( F ` z ) ) = ( abs ` ( F ` %s ) ) )' % (L, L))
sb3 = w.s([sb2], 'breq1d', '( z = %s -> ( ( abs ` ( F ` z ) ) <_ M <-> ( abs ` ( F ` %s ) ) <_ M ) )' % (L, L))
h2 = w.s([h], 'adantr', '( %s -> A. z e. ( A cseg B ) ( abs ` ( F ` z ) ) <_ M )' % A2)
lseg = w.s([a2, b2, t01, w.inst('cseglin')], 'syl3anc', '( %s -> %s e. ( A cseg B ) )' % (A2, L))
bd = w.s([sb3, h2, lseg], 'rspcdva', '( %s -> ( abs ` ( F ` %s ) ) <_ M )' % (A2, L))
fvr = w.s([fv], 'abscld', '( %s -> ( abs ` ( F ` %s ) ) e. RR )' % (A2, L)); m2 = w.s([m], 'adantr', '( %s -> M e. RR )' % A2)
bar2 = w.s([bar], 'adantr', '( %s -> ( abs ` ( B - A ) ) e. RR )' % A2); bage = w.s([ba2], 'absge0d', '( %s -> 0 <_ ( abs ` ( B - A ) ) )' % A2)
baj = w.s([bar2, bage], 'jca', '( %s -> ( ( abs ` ( B - A ) ) e. RR /\\ 0 <_ ( abs ` ( B - A ) ) ) )' % A2)
lm = w.s([fvr, m2, baj, bd, w.inst('lemul1a')], 'syl31anc', '( %s -> ( ( abs ` ( F ` %s ) ) x. ( abs ` ( B - A ) ) ) <_ %s )' % (A2, L, K))
le = w.s([am, lm], 'eqbrtrd', '( %s -> ( abs ` %s ) <_ %s )' % (A2, I, K))
il = w.s([ibab, ik, absr, kr2, le], 'itgle', '( %s -> %s <_ %s )' % (A, ITG(O01, '( abs ` %s )' % I), ITG(O01, K)))
icn = w.s([mb, vr, kc, w.inst('itgconst')], 'syl3anc', '( %s -> %s = ( %s x. ( vol ` ( 0 (,) 1 ) ) ) )' % (A, ITG(O01, K), K))
v2 = w.s([v1], 'oveq2d', '( %s -> ( %s x. ( vol ` ( 0 (,) 1 ) ) ) = ( %s x. 1 ) )' % (A, K, K)); m1 = w.s([kc], 'mulridd', '( %s -> ( %s x. 1 ) = %s )' % (A, K, K))
icn2 = w.s([icn, v2], 'eqtrd', '( %s -> %s = ( %s x. 1 ) )' % (A, ITG(O01, K), K)); icn3 = w.s([icn2, m1], 'eqtrd', '( %s -> %s = %s )' % (A, ITG(O01, K), K))
il2 = w.s([il, icn3], 'breqtrd', '( %s -> %s <_ %s )' % (A, ITG(O01, '( abs ` %s )' % I), K))
ir = w.s([cl, ib], 'itgcl', '( %s -> %s e. CC )' % (A, ITG(O01, I))); iar = w.s([ir], 'abscld', '( %s -> ( abs ` %s ) e. RR )' % (A, ITG(O01, I)))
iabr = w.s([absr, ibab], 'itgrecl', '( %s -> %s e. RR )' % (A, ITG(O01, '( abs ` %s )' % I)))
lt = w.s([iar, iabr, kr, ab1, il2], 'letrd', '( %s -> ( abs ` %s ) <_ %s )' % (A, ITG(O01, I), K))
w.qed([va, lt], 'eqbrtrd', '( %s -> ( abs ` %s ) <_ %s )' % (A, LINT('F', 'A', 'B'), K)); run(w)
